python3 << 'EOF'
t='............((....))...((...((....))..((...((....))...))..((....))...))..((....)).......................'
n=len(t)
stack=[]
pairs={}
for i,c in enumerate(t):
    if c=='(': stack.append(i)
    elif c==')':
        j=stack.pop(); pairs[j]=i; pairs[i]=j

# Build sequence: start with A everywhere, then assign pairs
seq=['A']*n
# Strategy: assign GC to all pairs (strong), but vary to avoid unwanted pairing
# Pair assignment: closing pairs GC, inner GC too. Use C-G or G-C.
# Let's assign: position i gets G if i < pairs[i], C if i > pairs[i] (i.e. G on 5' side, C on 3')
for i in range(n):
    if t[i]=='(':
        j=pairs[i]
        seq[i]='G'; seq[j]='C'
# Now set hairpin loops (the dots immediately inside a closing pair) to stable tetraloops
# Find hairpin loops: a '(' at i whose partner j, with region i+1..j-1 all dots and short
hairpin_loops=[]
for i in range(n):
    if t[i]=='(':
        j=pairs[i]
        inner=t[i+1:j]
        if '.' in inner and '(' not in inner and ')' not in inner:
            hairpin_loops.append((i,j,inner))
print('hairpin loops:')
for h in hairpin_loops: print(h, 'len', len(h[2]))
