import RNA
base='AAAAAAAAAAAACCGCACGGAAGGCAAAGGAGAACCAAUCGAUCGGAUACGUGAGAAGUCUACUGACACGCCAGCACACGCAAAAAAAAAAAAAAAAAAAAAAA'
target='............((....))...((...((....))..((...((....))...))..((....))...))..((....)).......................'
n=len(target)
pairs={}; stack=[]
for i,c in enumerate(target):
    if c=='(': stack.append(i)
    elif c==')':
        j=stack.pop(); pairs[j]=i; pairs[i]=j
tp=set((i,pairs[i]) for i in range(n) if i in pairs and i<pairs[i])
def sspairs(ss):
    st=[]; sp=set()
    for i,c in enumerate(ss):
        if c=='(': st.append(i)
        elif c==')': sp.add((st.pop(),i))
    return sp
comp={'G':'C','C':'G','A':'U','U':'A'}
# mutate 22,71 and 57,66 to NON-complementary
seqs=[]
for b22 in 'ACGU':
    for b71 in 'ACGU':
        if comp[b22]==b71: continue  # skip complementary
        s=list(base); s[22]=b22; s[71]=b71
        seqs.append(''.join(s))
for b57 in 'ACGU':
    for b66 in 'ACGU':
        if comp[b57]==b66: continue
        s=list(base); s[57]=b57; s[66]=b66
        seqs.append(''.join(s))
# also both pairs together
for b22 in 'ACGU':
    for b71 in 'ACGU':
        if comp[b22]==b71: continue
        for b57 in 'ACGU':
            for b66 in 'ACGU':
                if comp[b57]==b66: continue
                s=list(base); s[22]=b22; s[71]=b71; s[57]=b57; s[66]=b66
                seqs.append(''.join(s))
print('total seqs',len(seqs))
best=[];bd=999
for s in seqs:
    fc=RNA.fold_compound(s); fc.params=RNA.md(); fc.params.dangles=2
    ss,_=fc.mfe()
    sp=sspairs(ss)
    d=len(sp.symmetric_difference(tp))//2
    if d<bd: bd=d
    if d<=2: best.append((d,s))
best.sort()
print('best bd',bd)
for d,s in best[:5]: print(d,s)
